  function calcSeveranceNewTraced(totalMonths, avgWage, options = {}) {
    const trace = createTrace();
    addLaw(trace, {
      article: "\u52DE\u9000\u689D\u4F8B\xA712",
      description: "\u6BCF\u6EFF 1 \u5E74\u767C 0.5 \u500B\u6708\u5E73\u5747\u85AA\u8CC7\uFF0C\u6700\u9AD8 6 \u500B\u6708"
    });
    const basePerYear = resolveSeveranceBase(options.overrides);
    const capMonths = resolveSeveranceCap(options.overrides);
    if (basePerYear.overridden) {
      addLaw(trace, {
        article: basePerYear.sourceRef ?? "\u9662\u5167\u898F\u7BC4\uFF08\u512A\u65BC\u6CD5\u898F\uFF09",
        description: `\u8CC7\u9063\u57FA\u6578 ${basePerYear.value} \u6708/\u5E74\uFF08\u6CD5\u898F ${LEGAL_FLOOR.severance_base_per_year_months}\uFF09${basePerYear.note ? " \xB7 " + basePerYear.note : ""}`
      });
    }
    if (capMonths.overridden) {
      addLaw(trace, {
        article: capMonths.sourceRef ?? "\u9662\u5167\u898F\u7BC4\uFF08\u512A\u65BC\u6CD5\u898F\uFF09",
        description: `\u8CC7\u9063\u4E0A\u9650 ${capMonths.value} \u500B\u6708\uFF08\u6CD5\u898F ${LEGAL_FLOOR.severance_cap_months}\uFF09${capMonths.note ? " \xB7 " + capMonths.note : ""}`
      });
    }
    const years = totalMonths / 12;
    const rawMonths = years * basePerYear.value;
    const cappedMonths = Math.min(rawMonths, capMonths.value);
    const result = cappedMonths * avgWage;
    addStep(trace, {
      label: "\u670D\u52D9\u5E74\u8CC7\u63DB\u7B97",
      formula: "totalMonths / 12",
      inputs: { totalMonths },
      value: years,
      note: "\u670D\u52D9\u7E3D\u6708\u6578\u9664\u4EE5 12 \u5F97\u670D\u52D9\u5E74\u6578\uFF08\u542B\u5C0F\u6578\uFF09"
    });
    addStep(trace, {
      label: "\u57FA\u6578\u8A08\u7B97",
      formula: `years \xD7 ${basePerYear.value}`,
      inputs: { years },
      value: rawMonths,
      note: `\u6BCF\u6EFF 1 \u5E74 = ${basePerYear.value} \u500B\u6708\u5E73\u5747\u85AA\u8CC7` + (basePerYear.overridden ? `\uFF08\u8CB4\u9662\u898F\u7BC4\uFF0C\u6CD5\u898F\u4E0B\u9650 ${LEGAL_FLOOR.severance_base_per_year_months}\uFF09` : "")
    });
    if (rawMonths > capMonths.value) {
      addStep(trace, {
        label: "\u4E0A\u9650\u5957\u7528",
        formula: `min(basis, ${capMonths.value})`,
        inputs: { basis: rawMonths },
        value: cappedMonths,
        note: (capMonths.overridden ? `\u8CB4\u9662\u4E0A\u9650 ${capMonths.value} \u500B\u6708\uFF08\u512A\u65BC\u6CD5\u898F ${LEGAL_FLOOR.severance_cap_months}\uFF09` : "\u52DE\u9000\u689D\u4F8B\xA712 \u660E\u5B9A\u6700\u9AD8 6 \u500B\u6708") + "\uFF0C\u8D85\u904E\u90E8\u5206\u4E0D\u8A08"
      });
    }
    addStep(trace, {
      label: "\u8CC7\u9063\u8CBB\u91D1\u984D",
      formula: "basis \xD7 avgWage",
      inputs: { basis: cappedMonths, avgWage },
      value: result
    });
    setSummary(
      trace,
      `\u65B0\u5236\u8CC7\u9063\u8CBB ${Math.round(result).toLocaleString()} \u5143\uFF08\u57FA\u6578 ${cappedMonths.toFixed(2)} \u500B\u6708 \xD7 \u5E73\u5747\u85AA\u8CC7 ${Math.round(avgWage).toLocaleString()} \u5143\uFF09` + (basePerYear.overridden || capMonths.overridden ? " \xB7 \u5957\u7528\u9662\u5167\u898F\u7BC4" : "")
    );
    if (!basePerYear.overridden && !capMonths.overridden) {
      const ref = calcSeveranceNew(totalMonths, avgWage);
      if (Math.abs(ref - result) > 0.01) {
        throw new Error(
          `severance-traced \u65B0\u5236\u7D50\u679C\u8207 severance.calcSeveranceNew \u4E0D\u4E00\u81F4\uFF1Atraced=${result}, ref=${ref}`
        );
      }
    }
    return { result, trace };
  }
  function calcSeveranceOldTraced(totalMonths, avgWage) {
    const trace = createTrace();
    addLaw(trace, {
      article: "\u52DE\u57FA\u6CD5\xA717",
      description: "\u820A\u5236\u6BCF\u6EFF 1 \u5E74\u767C 1 \u500B\u6708\u5E73\u5747\u85AA\u8CC7\uFF0C\u4E0D\u8DB3 1 \u5E74\u6309\u6BD4\u4F8B\uFF0C\u7121\u4E0A\u9650"
    });
    const years = totalMonths / 12;
    const result = years * avgWage;
    addStep(trace, {
      label: "\u670D\u52D9\u5E74\u8CC7\u63DB\u7B97",
      formula: "totalMonths / 12",
      inputs: { totalMonths },
      value: years,
      note: "\u820A\u5236\u4E0D\u8DB3 1 \u5E74\u6309\u6BD4\u4F8B\u8A08\u7B97"
    });
    addStep(trace, {
      label: "\u57FA\u6578\u8A08\u7B97",
      formula: "years \xD7 1",
      inputs: { years },
      value: years,
      note: "\u820A\u5236\u6BCF\u6EFF 1 \u5E74 = 1 \u500B\u6708\uFF0C\u7121\u4E0A\u9650"
    });
    addStep(trace, {
      label: "\u8CC7\u9063\u8CBB\u91D1\u984D",
      formula: "basis \xD7 avgWage",
      inputs: { basis: years, avgWage },
      value: result
    });
    setSummary(
      trace,
      `\u820A\u5236\u8CC7\u9063\u8CBB ${Math.round(result).toLocaleString()} \u5143\uFF08\u57FA\u6578 ${years.toFixed(2)} \u500B\u6708 \xD7 \u5E73\u5747\u85AA\u8CC7 ${Math.round(avgWage).toLocaleString()} \u5143\uFF09`
    );
    const ref = calcSeveranceOld(totalMonths, avgWage);
    if (Math.abs(ref - result) > 0.01) {
      throw new Error(
        `severance-traced \u820A\u5236\u7D50\u679C\u8207 severance.calcSeveranceOld \u4E0D\u4E00\u81F4\uFF1Atraced=${result}, ref=${ref}`
      );
    }
    return { result, trace };
  }
  function calcNoticeTraced(calendarMonths, avgWage) {
    const trace = createTrace();
    addLaw(trace, {
      article: "\u52DE\u57FA\u6CD5\xA716",
      description: "\u4F9D\u5E74\u8CC7\u4E0D\u540C\uFF0C\u96C7\u4E3B\u7D42\u6B62\u5951\u7D04\u524D\u61C9\u65BC 10/20/30 \u65E5\u524D\u9810\u544A"
    });
    addStep(trace, {
      label: "\u5E74\u8CC7\u5224\u5B9A",
      formula: "\u4F9D calendarMonths \u5957 \xA716 \u4E09\u6BB5\u5F0F",
      inputs: { calendarMonths },
      value: calendarMonths
    });
    const result = calcNotice(calendarMonths, avgWage);
    addStep(trace, {
      label: "\u9810\u544A\u5929\u6578",
      formula: result.label,
      value: result.days,
      note: result.label
    });
    addStep(trace, {
      label: "\u672A\u9810\u544A\u61C9\u767C\u5DE5\u8CC7",
      formula: "avgWage / 30 \xD7 days",
      inputs: { avgWage, days: result.days },
      value: result.amount,
      note: "\u82E5\u96C7\u4E3B\u672A\u4F9D\xA716 \u9810\u544A\u800C\u9015\u884C\u7D42\u6B62\uFF0C\u61C9\u767C\u6B64\u91D1\u984D"
    });
    setSummary(
      trace,
      result.days === 0 ? "\u672A\u6EFF 3 \u500B\u6708\uFF0C\u7121\u9808\u9810\u544A" : `\u9810\u544A ${result.days} \u65E5\uFF1B\u672A\u9810\u544A\u9808\u767C ${Math.round(result.amount).toLocaleString()} \u5143`
    );
    return { result, trace };
  }

